//! GX-6's MCP tool `gx_probe` (safety Change since GX-7f, Read before: it maps a few pages of the carve-out and
//! one page per IOMMU, read-only; GX-7f: when no discovery copy exists in this boot and the carve-out gives none, it reads the copy
//! through MM_INDEX/MM_DATA as gx_bringup does, the index registers restored, nothing else written). GX-7b: the wide probe, every section reported even when one fails.
//! The desk runs it on the Mini-PC; QEMU has no AMD function and gets a plain refusal. GX-7d: `gx_bringup`
//! (safety Change), the first real PSP writes (`psplive`).

use alloc::string::String;
use alloc::vec;
use mcp::{Json, ToolContext, ToolError, ToolOutput, ToolResult};

/// `hex` (default false): append the whole binary as one hex line.
pub fn parse_args(args: &Json) -> Result<bool, ToolError> {
    match args.get("hex").filter(|v| !v.is_null()) {
        None => Ok(false),
        Some(v) => v.as_bool().ok_or_else(|| ToolError::BadArgument(String::from("hex (true or false)"))),
    }
}

fn gx_probe(_ctx: &ToolContext, args: &Json) -> ToolResult {
    let hex = parse_args(args)?;
    // GX-9b: its GC section reads registers: GC stays awake for it while the backend runs.
    let _awake = crate::hw::live::NODE.gpu().and_then(|g| g.dpm()).map(|d| d.awake());
    match crate::probe::run(hex) {
        None => Err(ToolError::Failed(String::from("no AMD GPU function (QEMU has none)"))),
        Some(Err(e)) => Err(ToolError::Failed(e)),
        Some(Ok(s)) => Ok(vec![ToolOutput::Text(s)]),
    }
}

mcp::mcp_tool!(
    name: "gx_probe",
    owner: "GX",
    safety: Change,
    description: "Radeon GPU wide read-only probe (GX-6/GX-7b: every section is reported even when one fails; GX-7f: no register is written but the MM_INDEX window when the discovery copy must be read through MM_INDEX/MM_DATA, as gx_bringup does, the index restored, never while a gx_bringup run holds the PSP; a 'discovery fetch:' line says so). Lines: 'gpu:' (function, IDs, every memory BAR with its real size), 'display:' (attached or why not), 'memsize:' (RCC_CONFIG_MEMSIZE), 'carve-out ...' (CPU address from MMMC_VM_FB_OFFSET or DCN_VM_FB_OFFSET and whether both agree, size, what BAR0 covers, the firmware memory map there, read-only samples at the start, under the discovery area and the discovery area itself (all 0xff / all zero / data), the GOP framebuffer through BAR0 compared with the carve-out, and a verdict), the discovery binary ('discovery:' ok or REFUSED or not available, 'ip ...' lines, harvest/GC/VCN/MALL tables, modules per role, firmware files, the device-ID table check; from the carve-out or the indirect copy of this boot), 'state:' (the start state: cold, after Linux, after a BitsOS Reload, after a clean BitsOS stop without GC, GC left unsettled, after a crash, PSP down (GX-7i2: BitsOS's stop note and this boot's own traces first, then the Linux signs); 'note from the kernel before:' (inherited with its text, or none with the reason) and 'note of this boot:'; the evidence, with the stop note the kernel before handed on; every PSP/SMU/SMUIO/NBIO/MMHUB/IH register and GFX_IMU_MSG_FLAGS (recorded only), and GC/GFXHUB only when SMUIO says GC is powered, each with value and meaning), 'bringup:' (the bring-up owner's write log totals; its gate is shut in GX-7b), 'iommu' (AMD-Vi: control register and IommuEn per IOMMU). hex=true appends the binary as one hex line (store it as the fixture)",
    schema: r#"{"type":"object","properties":{"hex":{"type":"boolean","description":"append the binary as hex (default false)"}}}"#,
    handler: gx_probe,
);

/// GX-7d/GX-7e/GX-7h: the first real PSP, SMU, GC and hub writes (the desk runs it on the Mini-PC; Georg 21.10.: GPU work needs no Georg).
fn gx_bringup(_ctx: &ToolContext, args: &Json) -> ToolResult {
    // GX-8c: changes nothing, and also answers on a machine without the chip.
    if args.get("until").and_then(|v| v.as_str()) == Some("boot") {
        return Ok(vec![ToolOutput::Text(crate::hw::boot::answer())]);
    }
    let a = crate::psplive::parse_args(args).map_err(ToolError::BadArgument)?;
    match crate::psplive::tool(a) {
        Ok(s) => Ok(vec![ToolOutput::Text(s)]),
        Err(e) => Err(ToolError::Failed(e)),
    }
}

